#include <iostream>
#include <unordered_map>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, k;
    std::cin >> n >> k;
    std::vector<int> a(n);
    for (int& x : a) std::cin >> x;

    std::unordered_map<int, int> counts;
    bool first = true;

    for (int i = 0; i < n; ++i) {
        ++counts[a[i]];
        if (i >= k) {
            auto it = counts.find(a[i - k]);
            if (--it->second == 0) counts.erase(it);   // zero is not "present"
        }
        if (i + 1 >= k) {
            if (!first) std::cout << ' ';
            std::cout << counts.size();
            first = false;
        }
    }
    std::cout << '\n';
}
